from pathlib import Path

core = Path("core/core-rule-full.md")
s = core.read_text(encoding="utf-8")
old = """### ● 死ぬまで戦う（Fight to the End）
敵は撤退しません。  
敵側が先制攻撃を行います。  
全滅するまで戦闘を継続します。
"""
new = """### ● 死ぬまで戦う（Fight to the End）
敵は通常の撤退を行いません。  
敵側が先制攻撃を行います。  
【死ぬまで戦う】は通常の撤退を行わないことを示す反応であり、それ自体では【ネゴシエーション】を禁止しません。【ネゴシエーション】の使用条件を満たした対象には通常どおり使用でき、成功した場合は【捕虜】または【鹵獲】として処理します。  
狂信的な敵、任務遂行のみを目的とする敵など、シナリオに【ネゴシエーション】無効と明記された対象には使用できません。  
全滅、【ネゴシエーション】による捕虜化・鹵獲、またはシナリオに定められた別の戦闘終了条件が成立するまで戦闘を継続します。
"""
if s.count(old) != 1:
    raise SystemExit(f"core anchor count={s.count(old)}")
core.write_text(s.replace(old, new, 1), encoding="utf-8")

scenario = Path("scenarios/missions/d66_lvl10-16_mission_01_blacksun.md")
b = scenario.read_text(encoding="utf-8")
redundant = """- 降伏交渉：
  反応が【死ぬまで戦う】であっても、この指揮官はCore v1.01の【ネゴシエーション】の対象から除外されない。生命点が1になった場合、通常どおり【ネゴシエーション】を使用でき、成功すれば捕虜にできる。【死ぬまで戦う】は通常の撤退を行わないことを示すもので、【ネゴシエーション】による捕虜化を禁止しない。
"""
if b.count(redundant) != 1:
    raise SystemExit(f"scenario redundant block count={b.count(redundant)}")
scenario.write_text(b.replace(redundant, "", 1), encoding="utf-8")

decisions = Path("docs/CORE_V1_01_P0_DECISIONS.md")
d = decisions.read_text(encoding="utf-8")
heading = "## 15. 【死ぬまで戦う】と【ネゴシエーション】 — 承認・反映済み"
section = """

## 15. 【死ぬまで戦う】と【ネゴシエーション】 — 承認・反映済み

ユーザー判断により、【死ぬまで戦う】と交渉不能を別概念として整理する。

- 【死ぬまで戦う】は、敵が通常の撤退を行わないことを示す反応とする。
- 【死ぬまで戦う】であること自体は、【ネゴシエーション】を禁止しない。
- 【ネゴシエーション】の通常の使用条件を満たした人物・有人高脅威目標には、反応が【死ぬまで戦う】でも使用できる。
- 成功した場合は通常どおり【捕虜】または【鹵獲】として処理し、その対象を戦闘から除外する。
- 狂信的な敵、任務遂行のみを目的とする敵など、本当に交渉不能とする対象はシナリオ側に【ネゴシエーション】無効と明記する。
- 【死ぬまで戦う】の戦闘は、全滅だけでなく、捕虜化・鹵獲またはシナリオ固有の別の戦闘終了条件が成立した場合にも終了し得る。

これにより、「撤退しない」と「交渉できない」を分離し、Coreの捕虜・鹵獲ルールを反応種別にかかわらず一貫して適用できる。
"""
if heading not in d:
    d = d.rstrip() + section + "\n"
decisions.write_text(d, encoding="utf-8")

audit = Path("docs/SCENARIO_V1_01_RESOURCE_BALANCE_AUDIT.md")
a = audit.read_text(encoding="utf-8")
heading2 = "## 56. 【死ぬまで戦う】と【ネゴシエーション】の共通化 — 採用済み"
section2 = """

## 56. 【死ぬまで戦う】と【ネゴシエーション】の共通化 — 採用済み

ユーザー承認により、Core v1.01では【死ぬまで戦う】を「通常の撤退を行わない反応」と定義し、【ネゴシエーション】の可否とは分離する。

- Black Sun出目64【路地裏の指揮官】にあった「【死ぬまで戦う】でも【ネゴシエーション】可能」という個別記載はCore共通規定と重複するため削除する。
- 出目64の指揮官は生命点1で通常どおり【ネゴシエーション】可能であり、成功時の捕虜報酬も維持する。
- 出目65【つぎはぎだらけの武装トラック】と出目66【即席装甲ガン・トラック】は有人車両であるため、反応が【死ぬまで戦う】でも生命点1で【ネゴシエーション】を使用でき、成功すれば乗員を【捕虜】、車両を【鹵獲】できる。
- 1周目最終戦のバリケードは無人対象として扱うため、反応が【死ぬまで戦う】でも【ネゴシエーション】対象にはならない。
- 将来、狂信者や自律兵器などを交渉不能にしたい場合は、反応種別に依存させずシナリオ側で【ネゴシエーション】無効を明記する。

これにより、【死ぬまで戦う】の意味を撤退制御に限定し、捕虜・鹵獲システムとの衝突を解消する。
"""
if heading2 not in a:
    a = a.rstrip() + section2 + "\n"
audit.write_text(a, encoding="utf-8")
